#!/usr/bin/env node
/**
 * D05 isolated-transport observation (owner: network).
 *
 * WHAT THIS PROVES
 *   A real authenticated direct-WSS loopback listener carries a real ACP frame
 *   round trip through the D05 layer:
 *     - real TLS material generated by `openssl`, real `wss://` loopback socket;
 *     - the listener's real HTTP `Authorization` admission (a wrong credential
 *       is refused before any frame is read);
 *     - the real `transport.hello` / `transport.hello_ack` handshake with
 *       generation, identity and admission checks;
 *     - a real Teams negotiation over the frozen frames, agreed on both sides;
 *     - a real `acp.open` / `acp.open_ack` with locally allocated channel keys
 *       and a refused stale `targetGeneration` (`acp.error STALE_GENERATION`);
 *     - a real `initialize` served from the captured result, a real `session/new`
 *       answered by the engine, a real permission callback to the controller and
 *       its reply restored to the engine, then `acp.close`;
 *     - two concurrent connections that stay isolated.
 *
 * WHAT THIS DOES NOT PROVE (read before citing it)
 *   - The peer engine is an IN-PROCESS SCRIPTED duplex, not a real OpenCode or
 *     DSH engine. The peer agent is in-process.
 *   - This is NOT the D05 two-real-engine LAN black box, and it is NOT D05
 *     closure. D05 cannot close until the two-real-engine run executes against
 *     the `--serve opencode` and `--serve dsh` entries.
 *   - One real `AcpHost` is exercised (the listener side). Two real `AcpHost`
 *     peers are not possible on one ACP channel: a callback arriving at the peer
 *     host would be handled as a client request.
 *   - Nothing here is installed-artifact, restart, or deployment evidence.
 *
 * Usage: node --experimental-transform-types \
 *          docs/evidence/acp-d05-network-20261010/isolated-transport-observation.mjs
 */
import { execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { assertAcpAllowed, extractAcpCapabilities, resolveAcpPolicy } from '../../../config/acp-policy.ts'
import { createAcpHost } from '../../../agent-host/acp-host.ts'
import { createDirectWssListener } from '../../../network/direct-listener.ts'
import { connectDirectWssTarget } from '../../../network/direct-route.ts'
import { buildDirectWssRoutePlan } from '../../../network/route-plan.ts'
import { createTeamsSession } from '../../../network/teams-session.ts'
import { negotiatedAgreement, runTeamsNegotiation } from '../../../network/teams-negotiation.ts'

const ENGINE_INSTANCE = 'engine-1'
const TARGET_GENERATION = 22
const SOURCE_GENERATION = 11
const CREDENTIAL = 'Bearer d05-observation-secret'
const ACP_CAPABILITIES = ['method:session/new', 'method:session/prompt', 'callback:session/request_permission']

const A = { accountId: 'account-1', scopeId: 'scope-1', agentId: 'agent-a' }
const B = { accountId: 'account-1', scopeId: 'scope-1', agentId: 'agent-b' }

const initializeResult = {
  jsonrpc: '2.0',
  id: 'runtime-initialize',
  result: {
    protocolVersion: 1,
    agentCapabilities: { promptCapabilities: { image: true, audio: false } },
    extension: { observation: 'captured-initialize-result' },
  },
}

let passed = 0
function assert(condition, message) {
  if (!condition) throw new Error(`OBSERVATION FAIL: ${message}`)
  passed += 1
  console.log(`  ok: ${message}`)
}

function withTimeout(promise, timeoutMs, label) {
  let timer
  const deadline = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`observation: timed out waiting for ${label}`)), timeoutMs)
  })
  return Promise.race([promise, deadline]).finally(() => clearTimeout(timer))
}

function wireOf(connection, peer) {
  return {
    peer,
    read: async () => JSON.parse((await connection.read()).bytes.toString('utf8')),
    send: async frame => { await connection.send({ bytes: Buffer.from(JSON.stringify(frame)), binary: false }) },
    closed: connection.closed,
    close: () => connection.close(),
  }
}

/**
 * One in-process duplex with two clearly separated directions: the host side
 * (`read`/`send`, which is what `AcpHost` uses) and the scripted engine side
 * (`engineRead`/`engineSend`). Sharing one queue between two readers would let
 * the host pump steal the engine's own replies.
 */
class ScriptedDuplex {
  constructor() {
    this.sent = []
    this.toHost = []
    this.hostWaiters = []
    this.toEngine = []
    this.engineWaiters = []
    this.closed = new Promise(() => undefined)
  }

  read() {
    const next = this.toHost.shift()
    if (next !== undefined) return Promise.resolve(next)
    return new Promise(resolve => { this.hostWaiters.push(resolve) })
  }

  send(frame) {
    this.sent.push(frame)
    const waiter = this.engineWaiters.shift()
    if (waiter !== undefined) waiter(frame)
    else this.toEngine.push(frame)
    return Promise.resolve()
  }

  engineRead() {
    const next = this.toEngine.shift()
    if (next !== undefined) return Promise.resolve(next)
    return new Promise(resolve => { this.engineWaiters.push(resolve) })
  }

  engineSend(frame) {
    const waiter = this.hostWaiters.shift()
    if (waiter !== undefined) waiter(frame)
    else this.toHost.push(frame)
    return Promise.resolve()
  }
}

function memoryHistory() {
  let sequence = 0
  return {
    records: [],
    async append(record) {
      sequence += 1
      const stored = { ...record, recordId: `obs-history-${sequence}`, sequence }
      this.records.push(stored)
      return stored
    },
  }
}

const directory = mkdtempSync(join(tmpdir(), 'd05-observation-'))
const sessions = []
const targets = []
let listener

function cleanup() {
  for (const session of sessions) void session.close().catch(() => undefined)
  for (const target of targets) void target.close().catch(() => undefined)
  void listener?.close().catch(() => undefined)
  rmSync(directory, { recursive: true, force: true })
}

async function main() {
  console.log('D05 isolated direct-WSS transport observation')
  console.log('NOTE: the peer engine is an in-process scripted duplex. This is NOT the D05 two-real-engine LAN black box.')

  // ---- real TLS material -------------------------------------------------
  execFileSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '1',
    '-subj', '/CN=localhost', '-addext', 'subjectAltName=IP:127.0.0.1',
    '-keyout', join(directory, 'key.pem'), '-out', join(directory, 'cert.pem')], { stdio: 'ignore' })
  const key = readFileSync(join(directory, 'key.pem'))
  const cert = readFileSync(join(directory, 'cert.pem'))
  assert(key.length > 0 && cert.length > 0, 'real TLS key and certificate material was generated')

  // ---- listener-side ACP host over a scripted in-process engine ----------
  const supported = extractAcpCapabilities(initializeResult, ['session/new', 'session/prompt', 'callback:session/request_permission'])
  const policy = resolveAcpPolicy({
    intent: { enabled: true, required: [], blacklist: [], clientCapabilities: [], callbackExecutor: 'controller' },
    engineInstanceId: ENGINE_INSTANCE,
    supported,
    enforceablePolicies: supported,
  })
  const duplex = new ScriptedDuplex()
  const history = memoryHistory()
  const host = createAcpHost({
    handle: {
      engineInstanceId: ENGINE_INSTANCE,
      pid: process.pid,
      targetGeneration: TARGET_GENERATION,
      acp: duplex,
      exited: new Promise(() => undefined),
    },
    initializeResult,
    policy,
    history,
    assertAllowed: assertAcpAllowed,
  })

  let promptEngineId
  void (async () => {
    for (;;) {
      const frame = await duplex.engineRead()
      if (frame.method === 'session/new') {
        await duplex.engineSend({ jsonrpc: '2.0', id: frame.id, result: { sessionId: 'session-1', _meta: { engine: 'in-process-scripted' } } })
        continue
      }
      if (frame.method === 'session/prompt') {
        promptEngineId = frame.id
        await duplex.engineSend({
          jsonrpc: '2.0',
          id: 'engine-callback-1',
          method: 'session/request_permission',
          params: {
            sessionId: 'session-1',
            toolCall: { toolCallId: 'tool-1' },
            options: [{ optionId: 'allow', name: 'Allow', kind: 'allow_once' }],
          },
        })
        continue
      }
      if (frame.id === 'engine-callback-1' && frame.result !== undefined) {
        await duplex.engineSend({
          jsonrpc: '2.0',
          id: promptEngineId,
          result: { stopReason: 'end_turn', _meta: { permission: frame.result.outcome.outcome } },
        })
      }
    }
  })().catch(() => undefined)

  // ---- real authenticated listener ---------------------------------------
  const accepted = []
  listener = await createDirectWssListener({
    host: '127.0.0.1',
    port: 0,
    key,
    cert,
    admissions: [{ admissionRef: 'adm-agent-a', peer: A, credential: CREDENTIAL }],
    target: {
      hostId: 'host-b',
      agentId: B.agentId,
      targetGeneration: TARGET_GENERATION,
      protocolVersion: 1,
      capabilitiesRevision: 'cap-b',
    },
    maxPayload: 262_144,
    maxConnections: 8,
    maxMessageBytes: 262_144,
    maxBufferedBytes: 262_144,
    maxPendingFrames: 64,
    helloTimeoutMs: 4_000,
    onConnection: async connection => {
      accepted.push(connection)
      const transport = wireOf(connection.connection, connection.peer)
      const negotiation = await runTeamsNegotiation({
        options: {
          side: 'responder',
          connectionId: connection.connectionId,
          self: B,
          peer: connection.peer,
          selfGeneration: TARGET_GENERATION,
          selfCapabilitiesRevision: 'cap-b',
          selfPolicyRevision: 7,
          allowedRoles: ['master', 'peer'],
          admittedCapabilities: ACP_CAPABILITIES,
          peerPolicyRevision: 3,
        },
        port: transport,
        timeoutMs: 5_000,
      })
      const session = createTeamsSession({
        negotiation,
        connectionId: connection.connectionId,
        transport,
        host,
        policy,
        engineInstanceId: ENGINE_INSTANCE,
        pollIntervalMs: 5,
      })
      sessions.push(session)
      void session.run().catch(() => undefined)
    },
  })
  assert(listener.url.startsWith('wss://127.0.0.1:'), `a real direct WSS listener is bound at ${listener.url}`)

  // ---- a wrong credential is refused by real admission -------------------
  const routePlan = () => buildDirectWssRoutePlan({
    hostId: 'host-b',
    directoryGeneration: 1,
    policy: 'manual',
    targetCandidateId: 'lan-1',
    candidates: [{ candidateId: 'lan-1', kind: 'lan', endpoint: listener.url, port: listener.port, authRequired: true, lastSeenAt: new Date().toISOString() }],
  })
  const hello = {
    hostId: 'host-b',
    agentId: B.agentId,
    targetGeneration: TARGET_GENERATION,
    protocolVersion: 1,
    capabilitiesRevision: 'cap-b',
    source: A,
    admissionRef: 'adm-agent-a',
  }
  const connect = async credential => await connectDirectWssTarget({
    transport: {
      endpoint: listener.url,
      credential,
      ca: cert,
      connectTimeoutMs: 4_000,
      maxMessageBytes: 262_144,
      maxBufferedBytes: 262_144,
      maxPendingFrames: 64,
    },
    hello,
    plan: routePlan(),
    helloTimeoutMs: 4_000,
  })

  let refusedError
  try {
    const bad = await connect('Bearer wrong-credential')
    targets.push(bad)
  } catch (error) {
    refusedError = error
  }
  assert(refusedError !== undefined,
    `a wrong credential is refused at real admission (${refusedError === undefined ? 'accepted' : String(refusedError.message).slice(0, 60)})`)
  assert(accepted.length === 0, 'the refused connection never reached the connection handler, so no application frame was read')

  // ---- session 1: full negotiation plus ACP round trip -------------------
  async function openSession(label) {
    const target = await connect(CREDENTIAL)
    targets.push(target)
    const transport = wireOf(target.connection, B)
    const negotiation = await runTeamsNegotiation({
      options: {
        side: 'initiator',
        connectionId: `conn-${label}`,
        self: A,
        peer: B,
        selfGeneration: SOURCE_GENERATION,
        selfCapabilitiesRevision: 'cap-a',
        selfPolicyRevision: 3,
        allowedRoles: ['master', 'peer'],
        requestedRole: 'master',
        requestedPeerRole: 'peer',
        requestedCapabilities: ACP_CAPABILITIES,
        requestId: `req-${label}`,
        expectedTargetGeneration: TARGET_GENERATION,
        expectedTargetCapabilitiesRevision: 'cap-b',
      },
      port: transport,
      timeoutMs: 5_000,
    })
    return { target, transport, negotiation, agreement: negotiatedAgreement(negotiation) }
  }

  const first = await openSession('one')
  assert(first.negotiation.state === 'agreed', 'the initiator reached the terminal agreed state over the real socket')
  assert(first.agreement.source.agentId === A.agentId && first.agreement.target.agentId === B.agentId,
    'the agreement carries the authenticated identities, never a frame-supplied identity')
  assert(Number.isSafeInteger(first.agreement.sourcePolicyRevision) && first.agreement.sourcePolicyRevision === 3 &&
    first.agreement.targetPolicyRevision === 7, 'the agreement carries integer accepted config revisions (R3), not hashed policy revisions')
  assert(first.agreement.targetGeneration === TARGET_GENERATION && first.agreement.sourceGeneration === SOURCE_GENERATION,
    'the agreement carries the negotiated generations')

  const clientRef = { connectionId: 'conn-one', channelId: 'client-channel-1', targetGeneration: TARGET_GENERATION, engineInstanceId: ENGINE_INSTANCE }
  await first.transport.send({ version: 1, kind: 'acp.open', ref: clientRef })
  const ack = await withTimeout(first.transport.read(), 5_000, 'acp.open_ack')
  assert(ack.kind === 'acp.open_ack', 'the listener answered acp.open with acp.open_ack')
  assert(ack.ref.channelId !== clientRef.channelId && ack.ref.connectionId !== clientRef.connectionId,
    'the listener allocated its own transport-scoped connectionId/channelId (R2)')
  assert(ack.ref.targetGeneration === TARGET_GENERATION && ack.ref.engineInstanceId === ENGINE_INSTANCE,
    'the ack ref was rebuilt from the local generation and engine instance, not echoed from the wire (R2)')

  async function readUntil(predicate, label, timeoutMs = 6_000) {
    const deadline = Date.now() + timeoutMs
    const seen = []
    while (Date.now() < deadline) {
      const frame = await withTimeout(first.transport.read(), timeoutMs, label)
      seen.push(frame)
      if (predicate(frame)) return frame
    }
    throw new Error(`observation: timed out waiting for ${label}; saw ${JSON.stringify(seen)}`)
  }

  await first.transport.send({ version: 1, kind: 'acp.frame', ref: clientRef, frame: { jsonrpc: '2.0', id: 1, method: 'initialize', params: { clientCapabilities: {} } } })
  const initialize = await readUntil(frame => frame.kind === 'acp.frame' && frame.frame.id === 1, 'initialize result')
  assert(initialize.frame.result.protocolVersion === 1 && initialize.frame.result.extension.observation === 'captured-initialize-result',
    'initialize was served from the captured result and preserved the payload byte-for-byte')

  await first.transport.send({ version: 1, kind: 'acp.frame', ref: clientRef, frame: { jsonrpc: '2.0', id: 2, method: 'session/new', params: { cwd: '/tmp', mcpServers: [] } } })
  const created = await readUntil(frame => frame.kind === 'acp.frame' && frame.frame.id === 2, 'session/new result')
  assert(created.frame.result.sessionId === 'session-1' && created.frame.result._meta.engine === 'in-process-scripted',
    'session/new reached the engine over the real socket and its result was relayed unchanged')

  await first.transport.send({ version: 1, kind: 'acp.frame', ref: clientRef, frame: { jsonrpc: '2.0', id: 3, method: 'session/prompt', params: { sessionId: 'session-1', prompt: [{ type: 'text', text: 'observe' }] } } })
  const callback = await readUntil(frame => frame.kind === 'acp.frame' && frame.frame.method === 'session/request_permission', 'permission callback')
  assert(callback.frame.id !== 'engine-callback-1', 'the engine callback id was rewritten for the controller and is restorable')
  await first.transport.send({
    version: 1,
    kind: 'acp.frame',
    ref: clientRef,
    frame: { jsonrpc: '2.0', id: callback.frame.id, result: { outcome: { outcome: 'selected', optionId: 'allow' } } },
  })
  const prompt = await readUntil(frame => frame.kind === 'acp.frame' && frame.frame.id === 3, 'prompt result')
  assert(prompt.frame.result.stopReason === 'end_turn' && prompt.frame.result._meta.permission === 'selected',
    'the controller reply was restored to the engine and the prompt result came back')

  await first.transport.send({ version: 1, kind: 'acp.close', ref: clientRef })
  const closedAt = Date.now() + 4_000
  while (sessions[0].channels.length !== 0 && Date.now() < closedAt) await new Promise(resolve => setTimeout(resolve, 10))
  assert(sessions[0].channels.length === 0, 'acp.close released the listener channel instead of restoring a callback or prompt')

  // ---- session 2: concurrency and isolation ------------------------------
  const second = await openSession('two')
  const secondRef = { connectionId: 'conn-two', channelId: 'client-channel-1', targetGeneration: TARGET_GENERATION, engineInstanceId: ENGINE_INSTANCE }
  await second.transport.send({ version: 1, kind: 'acp.open', ref: secondRef })
  const secondAck = await withTimeout(second.transport.read(), 5_000, 'second acp.open_ack')
  assert(secondAck.kind === 'acp.open_ack', 'a second concurrent connection opened its own channel')
  assert(secondAck.ref.connectionId !== ack.ref.connectionId && secondAck.ref.channelId !== ack.ref.channelId,
    'the two concurrent sessions hold distinct local channel keys')
  assert(accepted.length === 2 && accepted[0].connectionId !== accepted[1].connectionId,
    'the listener observed two distinct authenticated transport connections')

  // ---- stale generation is refused on the real socket --------------------
  const third = await openSession('three')
  const staleRef = { connectionId: 'conn-three', channelId: 'client-channel-1', targetGeneration: TARGET_GENERATION - 1, engineInstanceId: ENGINE_INSTANCE }
  await third.transport.send({ version: 1, kind: 'acp.open', ref: staleRef })
  const stale = await withTimeout(third.transport.read(), 5_000, 'stale acp.error')
  assert(stale.kind === 'acp.error' && stale.error.code === 'STALE_GENERATION',
    'a stale targetGeneration was refused with acp.error STALE_GENERATION (R2)')
  const forgedEngine = { connectionId: 'conn-three', channelId: 'client-channel-2', targetGeneration: TARGET_GENERATION, engineInstanceId: 'engine-forged' }
  await third.transport.send({ version: 1, kind: 'acp.open', ref: forgedEngine })
  const forged = await withTimeout(third.transport.read(), 5_000, 'forged acp.error')
  assert(forged.kind === 'acp.error' && forged.error.code === 'STALE_GENERATION',
    'a forged engineInstanceId was refused with acp.error STALE_GENERATION (R2)')

  // ---- the host only ever saw locally allocated refs ---------------------
  const hostRecords = history.records
  assert(hostRecords.length > 0 && hostRecords.every(record => record.kind === 'request'),
    `the listener host recorded ${hostRecords.length} request-history records through the injected port`)
  const localChannelIds = [...new Set(hostRecords.map(record => record.channelId).filter(Boolean))]
  assert(localChannelIds.length > 0 && localChannelIds.every(id => id.startsWith('teams-') && id !== clientRef.channelId),
    'every host record carries a locally allocated channelId, never the peer wire key (R2)')
}

try {
  await main()
  console.log(`\nOBSERVATION PASSED: ${passed} checks.`)
  console.log('NOT PROVEN: the peer engine was an in-process scripted duplex; this is not the D05 two-real-engine LAN black box and does not close D05.')
} catch (error) {
  console.error(`\nOBSERVATION FAILED: ${error instanceof Error ? error.stack ?? error.message : String(error)}`)
  process.exitCode = 1
} finally {
  cleanup()
}
